fix_code:
static void Test_Case() { 
   int n = fs.nextInt() ;
   int[] A = new int[n];
   for (int i = 0; i < n; i++) {
       A[i] = fs.nextInt();
   }
   long ans = 0;
   for (int i = 0; i < n; i++) {
       for (int j = i + 1; j < n; j++) {
           ans += Math.max(A[j] - A[i], 0);
       }
   }
   System.out.println(ans);
}

